def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    path = os.path.join(out_dir, "entry.png")
    with open(path, "wb") as f:
        f.write(base64.b64decode("".join(IMAGE_B64)))
    print("wrote", path)


if __name__ == "__main__":
    main()
